do $$
declare
  v_course_id uuid := '4a335bba-f8b8-4ff1-9dd5-e4003b9cb196';
  v_level uuid;
  -- modules.order_number is unique per COURSE, not per level (a course's
  -- modules are numbered continuously across all its levels) -- so this
  -- can't just start at 1 for a level beyond the first. Computed here
  -- instead of hardcoded so this script works correctly regardless of how
  -- many modules the course already has.
  v_module_offset int;
  v_m1 uuid;
  v_m2 uuid;
begin
  -- Appending to a level that already exists. Looked up rather than
  -- inserted, so this adds to the learner's current Level 1 instead of
  -- creating a duplicate one, and no existing module is re-parented.
  select id into v_level from public.levels
    where course_id = v_course_id and order_number = 1;

  if v_level is null then
    raise exception 'Level % not found for course % -- refusing to guess', 1, v_course_id;
  end if;

  -- The new modules must sit INSIDE this level, not at the end of the
  -- course. getOrderedLessons() builds the learner's lesson sequence from
  -- modules.order_number alone and ignores level, so a module appended at
  -- the course's max order would put beginner content after the final
  -- level's material. Insert straight after this level's last module and
  -- shift everything below it down instead.
  select coalesce(max(order_number), 0) into v_module_offset
    from public.modules where level_id = v_level;

  -- Two-phase shift: (course_id, order_number) is unique, and a single
  -- "+ N" update can trip that constraint mid-statement, so park the rows
  -- out of range first and bring them back afterwards.
  update public.modules set order_number = order_number + 1000
   where course_id = v_course_id and order_number > v_module_offset;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Drive, Sharing and Permissions', 'Where your files live, and who can get at them. Sharing is the point where a productivity tool becomes a security decision, and it is the thing people get wrong most often.', v_module_offset + 1)
  returning id into v_m1;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m1, 'Organising Drive So You Can Find Things', 'A practical tour of Google Drive — uploading, folders, the New menu, search and Quick Access. About 17 minutes.', 'https://www.youtube.com/watch?v=gdrxAoqfvbA', 1,
      array['Tell the difference between My Drive, Shared drives and Shared with me', 'Find a file in seconds using search operators rather than folder-digging', 'Explain why Shared with me is not storage you control'],
      'Drive stops being useful at roughly the point you stop being able to find things in it.

MY DRIVE is yours. Files here are owned by your account, count against your storage, and disappear for everyone if your account goes away.

SHARED WITH ME is not a folder. It is a list of files other people own and gave you access to. You cannot organise it, and if the owner deletes a file or revokes your access, it vanishes from your list. If you need a file to persist, make your own copy or add a shortcut to it in My Drive.

SHARED DRIVES, on paid Workspace plans, are owned by the organisation rather than a person. This matters enormously when someone leaves: files in a Shared drive stay, and files in that person''s My Drive leave with them. If a file matters to the business, it should not live in one individual''s My Drive.

For finding things, search beats folders once you pass a few hundred files. Drive''s search box takes operators, and two combined will find almost anything:

- type:spreadsheet, type:document, type:pdf
- owner:name@example.com
- before:2026-01-01 and after:2025-06-01
- title:budget (searches the file name only, rather than the contents)

The most common Drive mistake is filing by project AND by client AND by year, three levels deep, so nothing has one obvious home and you can never remember which branch you chose. One shallow structure plus good, consistent file names beats a deep tree every time.

Note that this walkthrough is a few years old, so some buttons have moved. The structure — My Drive, sharing, search — is unchanged.',
      'Open Drive and find three files using only the search box with an operator: one by type, one by owner, one by date range. Then pick a file in "Shared with me" that you actually rely on and add a shortcut to it in My Drive, so it stays reachable from your own structure rather than a list you cannot organise.',
      '[{"question":"A colleague leaves the company. Their files were in their My Drive and shared with you. What happens?","options":["The files can disappear when their account is removed","The files transfer to you automatically","Nothing — files shared with you are permanent","The files move into your own My Drive"],"correct_index":0},{"question":"What is \"Shared with me\"?","options":["A list of files other people own that you have been given access to","A folder stored inside My Drive","Your organisation''s backup of your files","The files you have shared with other people"],"correct_index":0}]'::jsonb),
    (v_m1, 'Sharing Correctly — Viewer, Commenter and Editor', 'A short, focused look at the Share button and the choice between edit, comment and view access, including link sharing to a wider group. Just over 3 minutes.', 'https://www.youtube.com/watch?v=TSImtOoHssg', 2,
      array['Choose the right permission level for what you actually want someone to do', 'Explain the risk of "Anyone with the link"', 'Understand what transferring ownership does and does not let you undo'],
      'Three roles, three very different levels of trust:

VIEWER — read only. Cannot change anything, cannot comment. Note that a Viewer can still download, copy and forward the file, so this is not confidentiality.

COMMENTER — read, and leave comments and suggestions, but cannot change the content. This is the right default for review and it is badly under-used. Most people hand out Editor when they mean Commenter.

EDITOR — full change rights, including deleting the content. By default an Editor can also change the sharing settings and invite other people, which means giving Editor is often giving away control over who else gets in. There is a setting to prevent that, under the gear icon in the share dialog. Use it.

NAMED PEOPLE VS A LINK. Sharing with named addresses ties access to identity — you can see exactly who has it and revoke one person. "Anyone with the link" means anyone who ever receives that link, forwarded any number of times, has access, with no record of who they are. A link pasted into a WhatsApp group, a public ticket, or an email thread that later gets forwarded is effectively public. Use named sharing for anything containing client data, personal information, or money.

"Restricted" is the safe default: only people explicitly added can open it, even if they somehow get the URL.

OWNERSHIP is separate from editing. The owner controls deletion and permanent access. You can transfer ownership to someone else in the same organisation — but once you do, you are just an editor on your own file and cannot take it back unilaterally. Transfer deliberately, and think carefully before doing it as you leave a role.

This video is short and covers the mechanics of the share dialog. The permission-level judgement above is written out here because it is the part that causes real problems and no short video covers it fully.',
      'Take one real file and share it three ways in turn: with a named colleague as Commenter, then as Editor with "Editors can change permissions and share" turned off, then look at what the "Anyone with the link" option would actually expose. Set it back to Restricted afterwards. Finally, open the sharing panel of a file someone else shared with you and work out what your own role on it is.',
      '[{"question":"You send a client a file set to \"Anyone with the link can view\". What is the actual risk?","options":["Anyone the link is forwarded to can open it, and you cannot tell who has done so","The client will not be able to open it without an account","Google deletes the file after 30 days","The file becomes read-only for you as well"],"correct_index":0},{"question":"You want someone to review a document and mark suggested changes without altering it. Which role?","options":["Commenter","Viewer","Editor","Owner"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  insert into public.modules (course_id, level_id, title, description, order_number) values
    (v_course_id, v_level, 'Real Collaboration in Google Docs', 'Editing someone else''s document directly is how collaboration goes wrong. Docs has tools built specifically to avoid that, and most people never touch them.', v_module_offset + 2)
  returning id into v_m2;

  insert into public.lessons (module_id, title, description, youtube_url, order_number, learning_objectives, notes, practice_activity, knowledge_check) values
    (v_m2, 'Comments, Suggesting Mode and @-mentions', 'From the full Google Docs walkthrough — watch the Share, Comments and Suggesting chapters. The whole video runs about 52 minutes, so use the chapter list to jump straight to those three.', 'https://www.youtube.com/watch?v=aoMMDlwEtwM', 1,
      array['Switch between Editing, Suggesting and Viewing mode and know when each is right', 'Accept and reject suggestions on your own document', 'Use comments and @-mentions to assign work rather than to chat'],
      'This lesson uses part of a longer walkthrough. Open the video''s chapter list and go to SHARE, COMMENTS and SUGGESTING — those three cover everything here. The rest of the video is useful but belongs to other lessons.

SUGGESTING MODE turns every change you make into a proposal: your text appears coloured and struck-through or underlined, with a card in the margin. The author sees exactly what you changed and clicks the tick or the cross. Nothing is lost either way. You switch modes from the pencil icon at the top right of the document.

Here is the connection back to the previous module: if you were given COMMENTER access, you are put into Suggesting mode automatically and cannot leave it. That is precisely why Commenter is the right role to hand out for review — the permission and the working mode reinforce each other.

COMMENTS attach to a selection rather than to the whole document. Select the text, press Ctrl+Alt+M (Cmd+Option+M on a Mac), and write the point. Resolve the thread once it is dealt with; resolved threads disappear from the margin but stay in the comment history, so the record survives without the clutter.

@-MENTIONS are the part most people never use and the part that actually does work. Typing @ and someone''s name inside a comment notifies them by email — and assigning the comment to that person turns it into a task with a checkbox that shows up for them. That converts "someone should fix this" into one specific person''s to-do.

The discipline that makes all of this work: comment on the specific sentence rather than writing "paragraph 3 is unclear" at the bottom, and say what you want changed rather than that you dislike it.',
      'Open one of your own documents, switch to Suggesting mode, and make three edits — a deletion, an insertion and a rewrite. Look at how each one is displayed, then accept one and reject another. Add a comment on a specific sentence and @-mention yourself, so you can see both the email notification and the assigned-task behaviour without bothering anyone.',
      '[{"question":"You are asked to review a colleague''s document without changing it. What should you do?","options":["Switch to Suggesting mode so every change is a proposal they can accept or reject","Edit it directly and tell them what you changed afterwards","Download a copy and edit that instead","Write all your changes at the end of the document"],"correct_index":0},{"question":"What does @-mentioning someone in a comment do, beyond notifying them?","options":["It can assign the comment to them as a task with a checkbox","It gives them Editor access to the document","It locks the paragraph so others cannot edit it","It resolves the comment thread automatically"],"correct_index":0}]'::jsonb),
    (v_m2, 'Version History — Getting Back What You Lost', 'From the same Google Docs walkthrough — this time watch the Version history chapter. Docs saves continuously, so version history is the only real undo for anything older than this session.', 'https://www.youtube.com/watch?v=aoMMDlwEtwM', 2,
      array['Open version history and read what changed and who changed it', 'Recover content from an old version without restoring the whole document', 'Name versions at the moments that actually matter'],
      'Same video as the previous lesson — jump to the VERSION HISTORY chapter.

Docs saves continuously, which means there is no save button to forget, and also no obvious way to undo yesterday. Version history is that undo.

File → Version history → See version history opens a timeline down the right-hand side. Each entry is a point in time with its contributors listed, and clicking one shows the document as it was, with each person''s changes colour-coded. Expanding an entry breaks it into finer increments.

There are two ways to recover, and the second is the one people miss:

RESTORE THIS VERSION rolls the whole document back. Nothing is destroyed — the current state stays in the history, so you can undo the restore itself.

COPY OUT OF AN OLD VERSION. Usually you only want the three paragraphs you deleted last week, not the whole of last week''s document. Open the old version, select the part you want, copy it, return to the current version, paste. This is far less disruptive than a full restore, and it is the right move on any document other people have edited since.

NAMING A VERSION — "Sent to client", "Before legal review" — turns an anonymous timestamp into a landmark you can actually find. Do it at the moments that matter. Scrolling a timeline of unnamed autosaves looking for "the version before we changed the price" is miserable, and entirely avoidable.

One thing worth knowing before you rely on it: version history is per-document and travels with the file. If you use "Make a copy", the copy starts fresh with no history at all.',
      'Open a document you have edited more than once and look at its version history — work out who changed what, and when. Name the current version something meaningful. Then delete a paragraph, wait for it to save, and recover just that paragraph by copying it out of the old version rather than restoring the whole document.',
      '[{"question":"You deleted three paragraphs last week and want them back, but the document has been edited a lot since. What is the least disruptive recovery?","options":["Open the old version, copy just those paragraphs, and paste them into the current document","Restore the entire old version and redo the week''s work","Ask everyone to retype their changes","Nothing can be recovered after a week"],"correct_index":0},{"question":"You duplicate a document with \"Make a copy\". What happens to its version history?","options":["The copy starts with no history","The full history is copied across with it","Only the named versions are carried over","History is shared between the two files from then on"],"correct_index":0}]'::jsonb)
  on conflict (module_id, order_number) do nothing;

  -- Bring the shifted modules back, now sitting after the 2 new one(s).
  update public.modules set order_number = order_number - 1000 + 2
   where course_id = v_course_id and order_number > 1000;

end $$;
